  drone:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none"><defs><linearGradient id="al3_drone_m" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#eef4f7"/><stop offset="1" stop-color="#778995"/></linearGradient><linearGradient id="al3_drone_b" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#75d2ff"/><stop offset="1" stop-color="#1676bd"/></linearGradient><filter id="al3_drone_s" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="1" stdDeviation=".8" flood-color="#071c2e" flood-opacity=".35"/></filter></defs><g filter="url(#al3_drone_s)" stroke="#173b57" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"><path d="M11 13h10l2 5H9z" fill="url(#al3_drone_m)"/><path d="m11 14-5-4m15 4 5-4M7 10H3m22 0h4" stroke-width="1.8"/><ellipse cx="4" cy="8.5" rx="3.5" ry="1.2" fill="url(#al3_drone_m)"/><ellipse cx="28" cy="8.5" rx="3.5" ry="1.2" fill="url(#al3_drone_m)"/><path d="M12 18v5m8-5v5M10 23h4m4 0h4" stroke="url(#al3_drone_b)" stroke-width="1.8"/><rect x="13" y="17" width="6" height="5" rx="1.2" fill="url(#al3_drone_b)"/><circle cx="16" cy="19.5" r="1.2" fill="#dff4ff"/></g></svg>',
