/* ALAGIS_PNG_SPRITE_END */
function ribIcon(cmd){
  if(RIB_CAT_ATUAL==='inicio' && cmd.ic && typeof RIB_PROJECT_PNG!=='undefined' && RIB_PROJECT_PNG[cmd.ic]){
    const p=RIB_PROJECT_PNG[cmd.ic];
    if(!document.documentElement.style.getPropertyValue('--alagis-project-png-sprite'))
      document.documentElement.style.setProperty('--alagis-project-png-sprite',`url("${RIB_PROJECT_PNG_SPRITE}")`);
    return `<span class="ric-project-png" style="--ix:${p[0]};--iy:${p[1]}"></span>`;
  }
  if(cmd.ic && typeof RIB_PNG!=='undefined' && RIB_PNG[cmd.ic]){
    const p=RIB_PNG[cmd.ic];
    if(!document.documentElement.style.getPropertyValue('--alagis-png-sprite'))
      document.documentElement.style.setProperty('--alagis-png-sprite',`url("${RIB_PNG_SPRITE}")`);
    return `<span class="ric-png" style="--ix:${p[0]};--iy:${p[1]}"></span>`;
  }
  if(cmd.ic && typeof RIB_SVG!=='undefined' && RIB_SVG[cmd.ic])
    return '<span class="ric-lib">'+RIB_SVG[cmd.ic]+'</span>';
  return '<span class="ric-png ric-png-missing" aria-hidden="true"></span>';
}
function ribFindSec(cont, key){
  // acha a seção real cujo título contém a palavra-chave (case/acentos livres)
  const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const alvo=norm(key);
  const secs=[...cont.querySelectorAll('.sec,.hsec')];
  for(const sec of secs){
    const h=sec.querySelector(':scope > h2, :scope > h3, h2, h3, label.field');
    if(h && norm(h.textContent).includes(alvo)) return sec;
  }
  return null;
}
let RIB_CAT_ATUAL='inicio';
/* Durante a execução de um comando da ribbon, a categoria que o usuário
   escolheu fica travada por um curto intervalo. Isso impede switchView() e
   callbacks assíncronos do comando de trocarem a aba visual (ex.: Cava ->
   Topografia/GIS) só porque várias categorias compartilham a mesma view. */
let RIB_COMMAND_CAT=null, RIB_COMMAND_CAT_TIMER=null;
function catAtual(){ return CATS.find(c=>c.id===RIB_CAT_ATUAL) || CATS[0]; }
const RIB_ORDER_KEY='alagis_ribbon_tab_order_v1';
let RIB_ORDER_OK=false, RIB_DRAG_ID=null, RIB_DRAG_T=0;
function ribCatOrderApply(){
  if(RIB_ORDER_OK) return; RIB_ORDER_OK=true;
  try{
    const ids=JSON.parse(localStorage.getItem(RIB_ORDER_KEY)||'[]');
    if(!Array.isArray(ids)||!ids.length) return;
    const pos=new Map(ids.map((id,i)=>[id,i]));
    CATS.sort((a,b)=>(pos.has(a.id)?pos.get(a.id):999)-(pos.has(b.id)?pos.get(b.id):999));
  }catch(e){}
}
function ribCatOrderSave(){
  try{ localStorage.setItem(RIB_ORDER_KEY,JSON.stringify(CATS.map(c=>c.id))); }catch(e){}
}
function ribTooltipBind(el,cmd,grupo,categoria){
  if(!el) return;
  el.removeAttribute('title');                 // evita a tooltip nativa duplicada
  const esconder=()=>{
    const t=document.getElementById('ribHoverTip');
    if(t) t.classList.remove('on');
  };
  el.addEventListener('mouseenter',()=>{
    let t=document.getElementById('ribHoverTip');
    if(!t){ t=document.createElement('div'); t.id='ribHoverTip'; document.body.appendChild(t); }
    const indisponivel=!!(cmd.visual||cmd.soon||(!cmd.act&&!cmd.sec&&!cmd.secKey));
    t.innerHTML='<b>'+esc(cmd.nome)+'</b>'+
      '<small>'+esc(categoria)+' · '+esc(grupo||'Comandos')+'</small>'+
      (cmd.desc?'<small style="margin-top:4px">'+esc(cmd.desc)+'</small>':'')+
      (indisponivel?'<small class="tip-soon">Em breve</small>':'<small style="margin-top:3px;color:#71c892">Comando disponível</small>');
    t.classList.add('on');
    const r=el.getBoundingClientRect();
    const w=t.offsetWidth, h=t.offsetHeight, m=7;
    let left=r.left+r.width/2-w/2;
    left=Math.max(m,Math.min(left,innerWidth-w-m));
    let top=r.bottom+7;
    if(top+h>innerHeight-m) top=r.top-h-7;
    t.style.left=Math.round(left)+'px'; t.style.top=Math.round(Math.max(m,top))+'px';
  });
  el.addEventListener('mouseleave',esconder);
  el.addEventListener('pointerdown',esconder);
}
/* Tooltips de todos os controles compactos. `title` e `aria-label` continuam
   sendo a fonte semântica; a dica visual é centralizada no alvo, aparece
   também por foco de teclado e é removida ao clicar/rolar. A observação de
   mutações cobre botões gerados depois (camadas, menus e modais). */
function uiIconTooltipInit(root=document){
  const seletor=[
    'button[title]','button[aria-label]','button.tbtn','button.mini','.dren-type-current',
    '.mtool[title]','.xbtn[title]','.gset[title]','.gdel[title]',
    '.mtool','.xbtn','.gset','.gdel','.a3-util[title]','[data-a3nav][title]','.a3-view-plus[title]',
    '#layoutTopTools [title]','#a3StatusViews [title]'
  ].join(',');
  const ehIcone=el=>{
    if(!el||el.dataset.uiTipBound||el.id==='ribHoverTip'||el.closest('#ribbon'))return false;
    const tx=(el.textContent||'').replace(/\s+/g,' ').trim(),aria=el.getAttribute('aria-label')||'',
      temSvg=!!el.querySelector('svg,.lo-top-ic,.ric,.ric-png,.ric-lib');
    return temSvg||!!aria||tx.length<=4||el.matches('.mtool,.xbtn,.gset,.gdel,.a3-util,[data-a3nav]');
  };
  const fecha=()=>{const t=document.getElementById('ribHoverTip');if(t){t.classList.remove('on','ui-icon-tip');}};
  const abre=el=>{
    const msg=(el.getAttribute('data-tooltip')||el.getAttribute('aria-label')||el.getAttribute('title')||'').trim();
    if(!msg)return;
    let t=document.getElementById('ribHoverTip');
    if(!t){t=document.createElement('div');t.id='ribHoverTip';document.body.appendChild(t);}
    t.innerHTML='<b>'+esc(msg)+'</b>';t.classList.add('on','ui-icon-tip');
    const r=el.getBoundingClientRect(),m=7,w=t.offsetWidth,h=t.offsetHeight;
    let left=Math.max(m,Math.min(r.left+r.width/2-w/2,innerWidth-w-m)),top=r.bottom+7;
    if(top+h>innerHeight-m)top=r.top-h-7;
    t.style.left=Math.round(left)+'px';t.style.top=Math.round(Math.max(m,top))+'px';
  };
  root.querySelectorAll?.(seletor).forEach(el=>{
    if(!ehIcone(el))return;
    el.dataset.uiTipBound='1';
    /* A dica customizada evita esperar a tooltip nativa; o texto acessível
       permanece no aria-label e em data-tooltip. */
    let dica=el.getAttribute('title')||el.getAttribute('aria-label')||'';
    if(!dica){
      const mapa={btnMenu:'Abrir menu principal',tabV3d:'Abrir visão 3D',cmdClose:'Fechar painel de comandos',
        btnLoPDF:'Exportar layout em PDF',btnLoPNG:'Exportar layout em PNG',btnLoSVG:'Exportar layout em SVG',
        drenTipoCurrent:'Escolher o tipo de dispositivo de drenagem',
        bufClose:'Fechar ferramenta de buffer',ddClose:'Fechar ferramenta',ffClose:'Fechar ferramenta'};
      const tx=(el.textContent||'').replace(/\s+/g,' ').trim();
      dica=mapa[el.id]||({PDF:'Exportar em PDF',PNG:'Exportar em PNG',SVG:'Exportar em SVG'})[tx]||
        (/^✕$/.test(tx)?'Fechar esta janela':'');
    }
    if(dica){el.dataset.tooltip=dica;if(!el.getAttribute('aria-label'))el.setAttribute('aria-label',dica);el.removeAttribute('title');}
    el.addEventListener('mouseenter',()=>abre(el));el.addEventListener('focus',()=>abre(el));
    el.addEventListener('mouseleave',fecha);el.addEventListener('blur',fecha);el.addEventListener('pointerdown',fecha);
  });
  if(!window.__alagisUiTipObserver){
    window.__alagisUiTipObserver=new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{
      if(n.nodeType===1)uiIconTooltipInit(n);
    })));
    window.__alagisUiTipObserver.observe(document.body,{childList:true,subtree:true});
    window.addEventListener('scroll',fecha,true);window.addEventListener('resize',fecha,{passive:true});
  }
}
setTimeout(()=>uiIconTooltipInit(document),0);
let RIB_FIT_RAF=0;
/* Rótulo que não cabe: o CSS quebra entre palavras em até duas linhas. Se
   ainda assim não couber — palavra única mais larga que o botão
   ("Sincronizar") ou texto que pediria três linhas —, a fonte DAQUELE rótulo
   diminui até caber (mínimo 72% e nunca abaixo de 6 px), em vez de partir a palavra ao meio
   ("Recupera / r") ou cortar com reticências ("Apagar..."). */
function ribRotulosCabem(bar){
  if(!bar) return;
  bar.querySelectorAll('.rbtn span:last-child').forEach(sp=>{
    sp.style.removeProperty('font-size');
    if(!sp.offsetParent||!sp.textContent.trim()) return;
    const base=parseFloat(getComputedStyle(sp).fontSize)||10;
    /* linhas de fato ocupadas (o desenho das letras passa 1 px da caixa com
       entrelinha justa; comparar alturas encolhia rótulos que já cabiam) */
    const linhas=()=>{const r=document.createRange();r.selectNodeContents(sp);
      return new Set([...r.getClientRects()].filter(q=>q.width>0).map(q=>Math.round(q.top))).size;};
    const naoCabe=()=>sp.scrollWidth>sp.clientWidth+1||linhas()>2;
    let f=base;
    const piso=Math.max(base*.72,6);              // abaixo de 6 px ninguém lê
    while(naoCabe()&&f>piso){
      f-=.25; sp.style.setProperty('font-size',f.toFixed(2)+'px','important');
    }
  });
}
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>{try{ribRotulosCabem(document.getElementById('ribbon'));}catch(_){}});
function ribbonFitOneRow(cat){
  const bar=document.getElementById('ribbon');
  if(!bar) return;
  if(!document.body.classList.contains('alagis3')){ requestAnimationFrame(()=>ribRotulosCabem(bar)); return; }
  cancelAnimationFrame(RIB_FIT_RAF);
  RIB_FIT_RAF=requestAnimationFrame(()=>{
    const groups=[...bar.querySelectorAll('.ribgrp')];
    if(!groups.length||bar.clientWidth<100) return;
    const cs=getComputedStyle(document.body);
    const baseBtn=parseFloat(cs.getPropertyValue('--rbtnw'))||64;
    const baseIcon=parseFloat(cs.getPropertyValue('--ricsz'))||34;
    const baseLabel=parseFloat(cs.getPropertyValue('--riclbl'))||10.5;
    let slots=0, buttons=0;
    groups.forEach(g=>{
      const n=g.querySelectorAll('.rbtn').length;
      buttons+=n;
      slots+=n;
    });
    if(!buttons||!slots) return;

    /* Espaço estrutural: margens da faixa, divisórias, preenchimento dos
       grupos e distância entre botões. Em telas estreitas ele também diminui,
       antes de reduzir os ícones. */
    const available=Math.max(80,bar.clientWidth-14);
    let gpad=available<1100?2:(available<1500?3:5);
    let gap=available<1100?0:1;
    const chrome=groups.length*(gpad*2+2)+Math.max(0,slots-groups.length)*gap;
    let btn=Math.floor((available-chrome)/slots);
    btn=Math.max(24,Math.min(baseBtn,btn));
    const ratio=Math.min(1,btn/baseBtn);
    const icon=Math.max(18,Math.min(baseIcon,Math.floor(baseIcon*Math.max(.57,ratio))));
    const label=Math.max(6.8,Math.min(baseLabel,baseLabel*Math.max(.66,Math.sqrt(ratio))));

    bar.style.setProperty('--fit-rbtnw',btn+'px');
    bar.style.setProperty('--fit-ricsz',icon+'px');
    bar.style.setProperty('--fit-riclbl',label.toFixed(2)+'px');
    bar.style.setProperty('--fit-ric-scale',(icon/48).toFixed(5));
    bar.style.setProperty('--fit-gpad',gpad+'px');
    bar.style.setProperty('--fit-gap',gap+'px');
    bar.style.setProperty('--fit-glabel',Math.max(7,Math.min(9,label-.6)).toFixed(2)+'px');
    bar.classList.add('ribbon-fit');
    ribRotulosCabem(bar);
    /* a faixa ainda se acomoda (ícones, abas) logo depois: mede de novo */
    clearTimeout(window.__alagisRibRotT);
    window.__alagisRibRotT=setTimeout(()=>{try{ribRotulosCabem(bar);}catch(_){}},160);
  });
}
if(!window.__alagisRibbonFitResize){
  window.__alagisRibbonFitResize=true;
  window.addEventListener('resize',()=>{
    clearTimeout(window.__alagisRibbonFitTimer);
    window.__alagisRibbonFitTimer=setTimeout(()=>{
      try{ ribbonFitOneRow(typeof catAtual==='function'?catAtual():null); }catch(e){}
    },80);
  },{passive:true});
}
function ribbonBuild(){
  const cats=document.getElementById('ribCats');
  const bar=document.getElementById('ribbon');
  if(!cats||!bar) return;
  ribbonClose(); ribCatOrderApply();
  /* A busca pertence visualmente à barra de abas. Antes de reconstruí-la,
     preserva o mesmo nó no cabeçalho oculto para não perder seus eventos. */
  const busca=document.querySelector('.a3-search-wrap');
  if(busca&&busca.parentElement===cats){
    const destino=document.querySelector('.a3-head-tools');
    if(destino)destino.insertBefore(busca,destino.firstChild);
  }
  cats.innerHTML=''; bar.innerHTML='';
  if(!acadOn()) return;
  // barra de categorias (17)
  CATS.forEach(c=>{
    const t=document.createElement('div'); t.className='ribcat'+(c.id===RIB_CAT_ATUAL?' on':'');
    t.textContent=c.nome; t.draggable=true; t.dataset.catId=c.id;
    t.title='Arraste para reorganizar esta aba';
    t.addEventListener('dragstart',e=>{
      RIB_DRAG_ID=c.id; RIB_DRAG_T=Date.now(); t.classList.add('dragging');
      e.dataTransfer.effectAllowed='move';
      try{ e.dataTransfer.setData('text/plain',c.id); }catch(err){}
    });
    t.addEventListener('dragover',e=>{ e.preventDefault(); e.dataTransfer.dropEffect='move'; });
    t.addEventListener('drop',e=>{
      e.preventDefault();
      const src=RIB_DRAG_ID, dst=c.id;
      if(!src||src===dst) return;
      const i=CATS.findIndex(x=>x.id===src), j=CATS.findIndex(x=>x.id===dst);
      if(i<0||j<0) return;
      const [mov]=CATS.splice(i,1);
      CATS.splice(j,0,mov);
      ribCatOrderSave(); RIB_DRAG_ID=null;
      ribbonBuild(); toast('Ordem das abas atualizada');
    });
    t.addEventListener('dragend',()=>{ RIB_DRAG_ID=null;RIB_DRAG_T=Date.now();t.classList.remove('dragging'); });
    t.onclick=()=>{
      if(RIB_DRAG_ID || Date.now()-RIB_DRAG_T<350) return;
      // sair de uma aba contextual do editor a descarta (ela é temporária)
      if(ED && ED._ctx && c.id!=='ed_ctx'){ try{ edFechaCtx(); }catch(e){} }
      RIB_CAT_ATUAL=c.id;
      if(S._view==='cava2'&&c.id==='editor'){ribbonBuild();return;}
      if(c.view) switchView(c.view); else ribbonBuild(); };
    cats.appendChild(t);
  });
  /* Mantém a busca imediatamente depois de AJUDA, mesmo quando as abas forem
     reorganizadas por arraste. */
  if(busca){
    const ajuda=cats.querySelector('[data-cat-id="ajuda"]');
    if(ajuda)ajuda.after(busca);else cats.appendChild(busca);
  }
  // ribbon: grupos da categoria ativa
  const cat=catAtual();
  const cont=document.getElementById(RIB_SRC[cat.view]||'sideMain');
  (cat.grupos||[]).forEach(grp=>{
    const g=document.createElement('div'); g.className='ribgrp'+(cat.id==='editor'?' ribgrp-grid':'');
    const items=document.createElement('div'); items.className='items';
    (grp.it||[]).forEach(cmd=>{
      const b=document.createElement('div'); b.className='rbtn'; b.title=cmd.nome;
      b.innerHTML='<span class="ric">'+ribIcon(cmd)+'</span><span>'+esc(cmd.nome)+'</span>';
      let sec=null;
      if(cont && !cmd.soon){
        if(cmd.sec) sec=cont.querySelector(cmd.sec) || document.querySelector(cmd.sec);
        else if(cmd.secKey) sec=ribFindSec(cont, cmd.secKey);
      }
      if(cmd.visual){
        b.classList.add('visual-only','soon');
        b.title=cmd.nome+' (em breve)';
        b.onclick=()=>emBreve(cmd.nome);
      }
      else if(sec){ b.onclick=()=>{
        if(!['inicio','projeto','arquivo','visualizacao','janela','config','ajuda'].includes(cat.id)&&!prepareDrawingCommand())return;
        const keepCat=RIB_CAT_ATUAL;
        RIB_COMMAND_CAT=keepCat; clearTimeout(RIB_COMMAND_CAT_TIMER);
        ribbonOpen(sec,b,cmd.nome);
        RIB_CAT_ATUAL=keepCat;
        RIB_COMMAND_CAT_TIMER=setTimeout(()=>{ RIB_COMMAND_CAT=null; },250);
      }; }
      else if(cmd.act && !cmd.soon){ b.onclick=()=>{
        if(!['inicio','projeto','arquivo','visualizacao','janela','config','ajuda'].includes(cat.id)&&!prepareDrawingCommand())return;
        const keepCat=RIB_CAT_ATUAL;
        RIB_COMMAND_CAT=keepCat; clearTimeout(RIB_COMMAND_CAT_TIMER);
        try{ cmd.act(b); }catch(e){
          const msg='Falha em “'+cmd.nome+'”: '+((e&&e.message)||e);
          try{cmdLog(msg,'erro');}catch(_){}
          try{console.error(e);}catch(_){}
          toast(msg);
        } finally {
          RIB_CAT_ATUAL=keepCat;
          RIB_COMMAND_CAT_TIMER=setTimeout(()=>{ RIB_COMMAND_CAT=null; },250);
        }
      }; }
      else {
        b.classList.add('soon'); b.title=cmd.nome+' (em breve)';
        b.onclick=()=>emBreve(cmd.nome);
      }
      ribTooltipBind(b,cmd,grp.label||'Comandos',cat.nome);
      items.appendChild(b);
    });
    g.appendChild(items);
    const lb=document.createElement('div'); lb.className='glabel'; lb.textContent=grp.label||'';
    g.appendChild(lb);
    bar.appendChild(g);
  });
  ribbonFitOneRow(cat);
  try{window.GeoMineBlasting?.syncWorkspace();}catch(e){console.warn('Blasting workspace',e);}
}
/* A coluna lateral permanece exclusiva para Camadas. Os controles do Layout
   vivem na paleta superior e os ajustes surgem logo abaixo dela. */
function layoutDockSync(v){
  const sec=document.getElementById('secLayout');
  const dock=document.getElementById('layoutDock');
  if(!sec||!dock) return;
  if(sec.classList.contains('docked')){
    sec.classList.remove('docked','layout-open');
    const volta=sec._voltaPara || document.getElementById('sideMain');
    if(volta && sec.parentNode!==volta) volta.appendChild(sec);
  }
  sec.style.display='none';dock.style.display='none';
  const legado=document.getElementById('layoutSideMenu');if(legado)legado.remove();
  try{ if(typeof layoutSideMenuSync==='function') layoutSideMenuSync(); }catch(e){}
}
function abreLayout(btn){
  switchView('layout');
  const sec=document.getElementById('secLayout');if(sec){sec.style.display='none';sec.classList.remove('layout-open');}
}
/* Mantém qualquer caixa temporária inteira dentro da janela. Ela pode cobrir a
   linha de comandos — temporários ficam acima dela — mas nunca é cortada pelo
   rodapé nem sai pelas bordas da tela. */
function popupFitViewport(el,left,top,margin){
  if(!el) return; const m=margin==null?8:margin;
  el.style.maxHeight=Math.max(80,innerHeight-2*m)+'px';
  el.style.overflowY='auto';
  el.style.left=Math.round(Math.max(m,Math.min(left,innerWidth-el.offsetWidth-m)))+'px';
  el.style.top=Math.round(Math.max(m,Math.min(top,innerHeight-el.offsetHeight-m)))+'px';
}
/* Ao abrir qualquer comando, a camada/superfície ativa no painel lateral é
   a fonte de trabalho padrão. Só altera seletores cuja opção traz também o
   NOME do objeto — isto evita confundir IDs iguais de raster e vetor. */
function commandUseActive(root){
  if(!root)return;
  let q;
  try{q=window.GeoMineCommandSelection?.capture({stamp:false});}catch(e){return;}
  if(q?.layers.length>1)return;
  const L=q?.layers[0]||((typeof processingLayer==='function')?processingLayer():
    ((typeof activeLayer==='function')?activeLayer():null));
  const R=(!L&&S.selRaster&&(S.rasters||[]).includes(S.selRaster))?S.selRaster:null;
  const alvo=L||R;if(!alvo)return;
  const id=String(alvo.id),nome=String(alvo.name||'').trim().toLowerCase();
  root.querySelectorAll('select').forEach(sel=>{
    // A comparação tem fontes/eixo próprios. A camada ativa não pode
    // recolocar uma fonte removida nem substituir uma escolha ao abrir ícones.
    if(['prRasterSel','prVectorSel','prAxisVectorSel'].includes(sel.id))return;
    const op=[...sel.options].find(o=>String(o.value)===id&&
      (!nome||String(o.textContent||'').toLowerCase().includes(nome)));
    if(!op)return;
    sel.value=op.value;
    try{sel.dispatchEvent(new Event('change',{bubbles:true}));}catch(e){}
  });
}
/* A sincronização ocorre antes do onclick do ícone. Assim também cobre
   comandos que abrem modal próprio e não passam por ribbonOpen(). */
document.addEventListener('pointerdown',e=>{
  if(e.target&&e.target.closest&&e.target.closest('#ribbon .rbtn'))commandUseActive(document);
},true);
function ribbonOpen(sec,btn,tit,persistent=true){
  // o painel de layout agora vive fixo no dock — nunca vai para o popover
  if(sec && sec.id==='secLayout' && sec.classList.contains('docked')){
    const r=document.getElementById('right'); if(r) r.classList.add('open');
    sec.classList.remove('collapsed');
    try{ sec.scrollIntoView({block:'start',behavior:'smooth'}); }catch(e){}
    return;
  }
  const pop=document.getElementById('ribbonPop'); if(!pop) return;
  // Repetir o clique no mesmo comando não desmonta a janela. O fechamento
  // é sempre uma ação explícita no botão ×.
  if(RIB.sec===sec && pop.classList.contains('on')) return;
  ribbonClose();
  pop.classList.toggle('profile-pop',sec.id==='sidePerfis');
  const prevDisplay=sec.style.display;
  RIB.ph=document.createComment('rib'); sec.parentNode.insertBefore(RIB.ph,sec);
  sec.style.display='block';
  sec.classList.remove('collapsed');
  pop.innerHTML='<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'+
    '<b style="font-size:12.5px;flex:1">'+esc(tit)+'</b>'+
    '<span class="gset" id="ribX" style="font-size:14px">✕</span></div>';
  pop.appendChild(sec);
  commandUseActive(sec);
  const r=btn.getBoundingClientRect();
  // Todo painel de ferramenta permanece aberto durante a operação no mapa.
  // O parâmetro é mantido por compatibilidade com os comandos existentes.
  pop.dataset.persistent='1';
  pop.classList.add('on');
  popupFitViewport(pop,r.left,r.bottom+4,8);
  RIB.sec=sec; RIB.btn=btn; RIB.prevDisplay=prevDisplay; btn.classList.add('on');
  const x=document.getElementById('ribX'); if(x) x.onclick=ribbonClose;
}
function ribbonClose(){
  const pop=document.getElementById('ribbonPop'); if(!pop) return;
  if(RIB.sec && RIB.ph && RIB.ph.parentNode){
    RIB.ph.parentNode.insertBefore(RIB.sec, RIB.ph); RIB.ph.remove();
    if(Object.prototype.hasOwnProperty.call(RIB,'prevDisplay'))
      RIB.sec.style.display=RIB.prevDisplay;
  }
  if(RIB.btn) RIB.btn.classList.remove('on');
  RIB={sec:null, ph:null, btn:null, prevDisplay:null};
  pop.classList.remove('on','profile-pop'); pop.innerHTML=''; delete pop.dataset.persistent;
}
document.addEventListener('pointerdown',e=>{
  const pop=document.getElementById('ribbonPop');
  if(!pop || !pop.classList.contains('on')) return;
  if(pop.contains(e.target) || e.target.closest('.rbtn')) return;
  // cliques em modais/menus abertos por cima não fecham o painel
  if(e.target.closest('.modal-bg,.modal')) return;
  // Operações no mapa, em menus ou em controles externos não fecham a janela.
  // Somente o botão × criado por ribbonOpen chama ribbonClose().
  return;
});
/* Regra única de permanência para todos os modais: clicar no fundo não é um
   comando de fechamento. Os fluxos exibem o próprio ×, Cancelar ou Concluir.
   A captura também neutraliza listeners antigos ligados ao backdrop. */
document.addEventListener('click',e=>{
  const alvo=e.target;
  if(alvo && alvo.classList && alvo.classList.contains('modal-bg') && alvo.classList.contains('on')){
    e.preventDefault();
    e.stopImmediatePropagation();
  }
},true);
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){
    const pop=document.getElementById('ribbonPop');
    // Esc é reservado para as ferramentas; não fecha o painel de parâmetros.
    if(pop && pop.classList.contains('on')) e.preventDefault();
  }
});
/* -------- paleta de PROPRIEDADES da camada ativa (esquerda) -------- */
/* -------- propriedades geométricas de uma feição (para a paleta) -------- */
function featZs(f){                  // achata todas as cotas Z da feição, se houver
  if(!f || !f.zg) return [];
  const out=[]; const push=v=>{ if(v!=null && isFinite(v)) out.push(+v); };
  (Array.isArray(f.zg[0])? f.zg : [f.zg]).forEach(r=>{ if(Array.isArray(r)) r.forEach(push); else push(r); });
  return out;
}
function featGeomInfo(L, f){
  if(!f || !f.geom) return null;
  const info={tipo:L.gtype, partes:0, verts:0, fechada:null, sentido:null,
    area:null, perim:null, comp:null, z:false, zmin:null, zmax:null};
  const zs=featZs(f); if(zs.length){ info.z=true; info.zmin=Math.min(...zs); info.zmax=Math.max(...zs); }
  if(L.gtype==='point'){ info.verts=f.geom.length; info.partes=f.geom.length; return info; }
  const rings=(f.multi&&Array.isArray(f.geom[0][0]))? f.geom : [f.geom];
  info.partes=rings.length;
  let per=0, comp=0, areaTot=0; let primeiro=true;
  for(const r of rings){
    info.verts+=r.length;
    let L2c=0; for(let i=0;i<r.length-1;i++) L2c+=Math.hypot(r[i+1][0]-r[i][0], r[i+1][1]-r[i][1]);
    const a=r[0], b=r[r.length-1];
    const fech = r.length>=4 && Math.hypot(a[0]-b[0],a[1]-b[1]) <= Math.max(1e-6, 0.001*Math.sqrt(Math.abs(ringArea(r))||1));
    if(primeiro){ info.fechada=fech; primeiro=false; }
    if(L.gtype==='polygon' || fech){
      const ar=ringArea(r);                       // >0 anti-horário, <0 horário (Y para cima)
      if(primeiro || info.sentido===null) info.sentido = ar>=0 ? 'anti-horário' : 'horário';
      areaTot+=Math.abs(ar); per+=L2c;
    } else { comp+=L2c; }
  }
  // sentido do anel externo (o de maior |área|)
  let maiorA=-1, sent=null;
  for(const r of rings){ const ar=ringArea(r); if(Math.abs(ar)>maiorA){ maiorA=Math.abs(ar); sent=ar>=0?'anti-horário':'horário'; } }
  if(L.gtype==='polygon' || info.fechada) info.sentido=sent;
  if(areaTot>0){ info.area=areaTot; info.perim=per; }
  if(comp>0) info.comp=comp;
  return info;
}
function fmtNum(v,dec){ return (v==null||!isFinite(v))?'—':
  Number(v).toLocaleString('pt-BR',{minimumFractionDigits:dec,maximumFractionDigits:dec}); }

function ppGeomHTML(L){
  // feição em foco: a selecionada no mapa (se for desta camada), senão a 1ª
  let f=null, rot='';
  if(S.selFeat && S.selFeat.layerId===L.id){ f=L.features[S.selFeat.idx]; rot=' (selecionada)'; }
  else if(L.features.length){ f=L.features[0]; rot=L.features.length>1? ' (1ª feição)':''; }
  const g=f? featGeomInfo(L,f):null;
  let linhas='';
  const li=(k,v)=>{ linhas+='<div style="display:flex;justify-content:space-between;gap:8px;padding:1px 0">'+
    '<span style="color:var(--ink-dim)">'+k+'</span><b style="font-family:var(--mono);font-size:11px">'+v+'</b></div>'; };
  if(g){
    li('Tipo', esc(g.tipo)+(g.z?' · 3D':' · 2D'));
    if(g.partes>1) li('Partes', g.partes);
    li('Vértices', g.verts);
    if(g.tipo!=='point'){
      if(g.fechada!=null){
        if(g.tipo==='polygon' && !g.fechada)
          li('Fechada', '<button class="mini" id="ppClosePoly" title="Acrescentar o primeiro vértice ao final do contorno" style="margin:0;padding:3px 7px;color:var(--amber)">não · fechar agora</button>');
        else li('Fechada', g.fechada?'sim':'não');
      }
      if(g.sentido) li('Sentido', g.sentido);
    }
    if(g.area!=null){ li('Área', fmtNum(g.area,2)+' m²'); li('Área (ha)', fmtNum(g.area/1e4,4)); li('Perímetro', fmtNum(g.perim,2)+' m'); }
    if(g.comp!=null) li('Comprimento', fmtNum(g.comp,2)+' m');
    if(g.z){ li('Cota máx.', fmtNum(g.zmax,3)+' m'); li('Cota mín.', fmtNum(g.zmin,3)+' m');
      li('Desnível', fmtNum(g.zmax-g.zmin,3)+' m'); }
  } else linhas='<div class="hint">Camada sem feições.</div>';
  return '<div style="border-top:1px dashed var(--line);margin-top:10px;padding-top:8px">'+
    '<label class="field">Geometria'+rot+'</label>'+
    '<div style="font-size:11.5px;line-height:1.5;margin-top:3px">'+linhas+'</div>'+
    (L.features.length>1 && !(S.selFeat&&S.selFeat.layerId===L.id)?
      '<div class="hint" style="margin-top:4px"><button type="button" class="gm-prop-info" data-prop-help="" aria-label="Ajuda: Geometria" aria-expanded="false"><span aria-hidden="true">i</span><span hidden>Toque numa feição no mapa (◈) para ver a geometria dela.</span></button></div>':'')+
    '</div>';
}
function ppAttrHTML(L){
  const selected=ppSelectedFeature(L);
  if(selected){
    const props=selected.f.props||{},names=[...new Set([...(L.fields||[]).map(f=>typeof f==='string'?f:f&&f.name),...Object.keys(props)].filter(Boolean))];
    return '<div data-prop-selection="attributes" style="border-top:1px dashed var(--line);margin-top:10px;padding-top:8px;overflow-wrap:anywhere">'+
      '<label class="field">Atributos da feição selecionada (#'+selected.idx+')</label>'+
      (names.length?names.map(n=>{
        const v=props[n],text=v==null?'—':typeof v==='object'?JSON.stringify(v):String(v);
        return '<div style="display:grid;grid-template-columns:minmax(0,2fr) minmax(0,3fr);gap:8px;padding:3px 0">'+
          '<span style="color:var(--ink-dim);overflow-wrap:anywhere">'+esc(n)+'</span>'+
          '<b style="text-align:right;font-size:11px;overflow-wrap:anywhere">'+esc(text)+'</b></div>';
      }).join(''):'<div class="hint">Feição sem atributos.</div>')+'</div>';
  }
  // colunas da tabela de atributos: nomes + tipo inferido
  const campos=(L.fields||[]).map(f=>typeof f==='string'?{name:f}:f).filter(f=>f&&f.name);
  let nomes=campos.map(c=>c.name);
  if(!nomes.length){                                  // sem fields definidos: deduz das props
    const set=new Set(); (L.features||[]).slice(0,50).forEach(f=>{ if(f.props) Object.keys(f.props).forEach(k=>set.add(k)); });
    nomes=[...set];
  }
  let corpo;
  if(!nomes.length) corpo='<div class="hint">Sem colunas de atributo.</div>';
  else{
    const tipoDe=n=>{ for(const f of (L.features||[])){ const v=f.props&&f.props[n];
      if(v==null||v==='') continue; return (typeof v==='number'||(!isNaN(parseFloat(v))&&isFinite(v)))?'nº':'texto'; } return '—'; };
    corpo='<div style="max-height:150px;overflow:auto;font-size:11.5px">'+
      nomes.map(n=>'<div style="display:flex;justify-content:space-between;gap:8px;padding:1px 0">'+
        '<span style="font-family:var(--mono)">'+esc(n)+'</span>'+
        '<span style="color:var(--ink-dim)">'+tipoDe(n)+'</span></div>').join('')+'</div>';
  }
  return '<div style="border-top:1px dashed var(--line);margin-top:10px;padding-top:8px">'+
    '<label class="field">Tabela de atributos · '+nomes.length+' coluna(s)</label>'+
    corpo+
    '</div>';
}
function attrFilterFields(L){
  const out=[],seen=new Set();
  (L.fields||[]).forEach(f=>{const n=typeof f==='string'?f:f&&f.name;if(n&&!seen.has(n)){seen.add(n);out.push(n);}});
  if(!out.length)(L.features||[]).slice(0,100).forEach(f=>Object.keys((f&&f.props)||{}).forEach(n=>{if(!seen.has(n)){seen.add(n);out.push(n);}}));
  return out;
}
function ppAttrFilterHTML(L){
  const fields=attrFilterFields(L),q=L.attrFilter||{},n=attrFilterCount(L),active=!!(q.enabled!==false&&q.field);
  const ops=[['eq','igual a'],['neq','diferente de'],['contains','contém'],['notcontains','não contém'],
    ['starts','começa com'],['ends','termina com'],['in','está na lista'],['gt','maior que'],['gte','maior ou igual'],
    ['lt','menor que'],['lte','menor ou igual'],['between','entre'],['empty','está vazio'],['notempty','não está vazio']];
  return '<div style="border:1px solid '+(active?'var(--amber)':'var(--line)')+';border-radius:8px;padding:8px;margin:8px 0">'+
    '<label class="field" style="display:flex;justify-content:space-between;gap:6px"><span>⌯ Filtro por atributo</span><span style="color:'+(active?'var(--amber)':'var(--ink-dim)')+'">'+
      (active?n.toLocaleString('pt-BR')+' de '+L.features.length.toLocaleString('pt-BR'):L.features.length.toLocaleString('pt-BR')+' feições')+'</span></label>'+
    (fields.length?'<div class="row2" style="margin-top:5px"><select id="ppFltField" title="Campo da tabela usado no filtro">'+
      '<option value="">— escolha o campo —</option>'+fields.map(f=>'<option value="'+esc(f)+'" '+(q.field===f?'selected':'')+'>'+esc(f)+'</option>').join('')+'</select>'+
      '<select id="ppFltOp" title="Condição do filtro">'+ops.map(([v,t])=>'<option value="'+v+'" '+((q.op||'eq')===v?'selected':'')+'>'+t+'</option>').join('')+'</select></div>'+
      '<div class="row2" id="ppFltValues" style="margin-top:5px"><input id="ppFltValue" list="ppFltSuggestions" value="'+esc(q.value??'')+'" placeholder="valor ou lista: A, B, C" title="Valor procurado">'+
      '<input id="ppFltValue2" value="'+esc(q.value2??'')+'" placeholder="valor final" title="Segundo valor, usado pelo operador entre"></div><datalist id="ppFltSuggestions"></datalist>'+
      '<label style="display:flex;align-items:center;gap:6px;font-size:11px;margin-top:5px"><input id="ppFltCase" type="checkbox" '+(q.caseSensitive?'checked':'')+' style="width:auto">Diferenciar maiúsculas e minúsculas</label>'+
      '<div class="row2" style="margin-top:6px"><button class="tbtn" id="ppFltApply" style="justify-content:center;background:var(--amber);color:#1a1206;font-weight:700">✓ Aplicar filtro</button>'+
      '<button class="tbtn" id="ppFltClear" style="justify-content:center" '+(active?'':'disabled')+'>× Limpar</button></div>':
      '<div class="hint">Esta camada não possui campos de atributos.</div>')+
    '<div class="hint" style="margin-top:5px"><button type="button" class="gm-prop-info" data-prop-help="" aria-label="Ajuda: Filtro de atributos" aria-expanded="false"><span aria-hidden="true">i</span><span hidden>O filtro não apaga dados e também é aplicado ao 3D, Layout, rótulos e exportações.</span></button></div></div>';
}
function attrFilterSuggestions(L,field){
  const dl=document.getElementById('ppFltSuggestions');if(!dl)return;const vals=new Set();
  for(const f of (L.features||[])){const v=f&&f.props?f.props[field]:null;if(v!=null&&String(v)!=='')vals.add(String(v));if(vals.size>=250)break;}
  dl.innerHTML=[...vals].sort((a,b)=>a.localeCompare(b,'pt-BR',{numeric:true})).map(v=>'<option value="'+esc(v)+'"></option>').join('');
}
function attrFilterApplyUi(L){
  const field=(document.getElementById('ppFltField')||{}).value||'',op=(document.getElementById('ppFltOp')||{}).value||'eq',
    value=(document.getElementById('ppFltValue')||{}).value??'',value2=(document.getElementById('ppFltValue2')||{}).value??'',
    caseSensitive=!!(document.getElementById('ppFltCase')||{}).checked;
  if(!field){toast('Escolha o campo que será filtrado');return;}
  if(!['empty','notempty'].includes(op)&&String(value).trim()===''){toast('Informe o valor do filtro');return;}
  if(op==='between'&&String(value2).trim()===''){toast('Informe o valor inicial e o valor final');return;}
  L.attrFilter={enabled:true,field,op,value,value2,caseSensitive};
  if(S.selFeat&&S.selFeat.layerId===L.id&&!attrFilterMatch(L,L.features[S.selFeat.idx])){S.selFeat=null;try{highlightSel();}catch(e){}}
  S.msel.items=(S.msel.items||[]).filter(it=>{const X=S.layers.find(x=>x.id===it.layerId),f=X&&X.features[it.idx];return X&&f&&attrFilterMatch(X,f);});
  try{mselHL();mselCount();}catch(e){}drawLayer(L);refreshUI();
  toast('Filtro aplicado: '+attrFilterCount(L).toLocaleString('pt-BR')+' de '+L.features.length.toLocaleString('pt-BR')+' feições');
}
function attrFilterClear(L){delete L.attrFilter;drawLayer(L);refreshUI();toast('Filtro removido — todas as feições estão visíveis');}
/* geometria de um raster/MDT para a paleta: extensão 2D, área 3D real
   (soma das faces dos 2 triângulos de cada célula válida), cotas e células.
   CACHEADO por raster (r._geomInfo) — o cálculo varre a grade e não pode
   rodar a cada clique. Área 3D só é calculada até um teto de células; acima
   dele usa uma amostragem regular (mantém a razão 3D/2D representativa). */
function rasterGeomInfo(r){
  if(!r) return null;
  if(r._geomInfo && r._geomInfoKey===(r.d&&r.d.z&&r.d.z.length)) return r._geomInfo;
  const d=r.d||r; if(!d||!d.z||!d.nc){ return null; }
  const nc=d.nc, nr=d.nr, csx=d.cs, csy=(d.csy||d.cs);
  const z=d.z;
  let zmin=Infinity, zmax=-Infinity, nVal=0;
  for(let k=0;k<z.length;k++){ const v=z[k]; if(v!=null&&isFinite(v)){ nVal++; if(v<zmin)zmin=v; if(v>zmax)zmax=v; } }
  if(!nVal){ const g0={nc,nr,csx,csy,nVal:0}; r._geomInfo=g0; r._geomInfoKey=z.length; return g0; }
  const area2D = nVal*csx*csy;
  // área 3D — com teto: acima de AREA3D_MAX células, amostra de STEP em STEP
  const AREA3D_MAX=8e6;
  const total=(nc-1)*(nr-1);
  const step = total>AREA3D_MAX ? Math.ceil(Math.sqrt(total/AREA3D_MAX)) : 1;
  let area3D=0, quads=0;
  const at=(i,j)=> (i>=0&&i<nc&&j>=0&&j<nr)? z[j*nc+i] : NaN;
  const triArea=(az,bz,cz,dx1,dy1,dx2,dy2)=>{
    // dois vetores no plano da célula (passo real em metros), z variável
    const ux=dx1,uy=dy1,uz=bz-az, vx=dx2,vy=dy2,vz=cz-az;
    const nx=uy*vz-uz*vy, ny=uz*vx-ux*vz, nz=ux*vy-uy*vx;
    return 0.5*Math.hypot(nx,ny,nz);
  };
  const sx=csx*step, sy=csy*step;                 // passo real da amostra (m)
  for(let j=0;j+step<nr;j+=step) for(let i=0;i+step<nc;i+=step){
    const z00=at(i,j), z10=at(i+step,j), z01=at(i,j+step), z11=at(i+step,j+step);
    if(![z00,z10,z01,z11].every(isFinite)) continue;
    area3D+=triArea(z00,z10,z01, sx,0, 0,sy);
    area3D+=triArea(z10,z11,z01, 0,sy, -sx,sy);
    quads++;
  }
  // se amostrou, escala a área pela fração coberta (quads·step² ≈ total de quads)
  let area3Dtot=null;
  if(quads){ area3Dtot = (step>1) ? area3D*(total/(quads*step*step)) : area3D; }
  const info={nc,nr,csx,csy,nVal, area2D, area3D:area3Dtot, zmin,zmax, amostrado:(step>1)};
  r._geomInfo=info; r._geomInfoKey=z.length;
  return info;
}
function ppRasterHTML(r){
  const g=rasterGeomInfo(r);
  let linhas='';
  const li=(k,v)=>{ linhas+='<div style="display:flex;justify-content:space-between;gap:8px;padding:1px 0">'+
    '<span style="color:var(--ink-dim)">'+k+'</span><b style="font-family:var(--mono);font-size:11px">'+v+'</b></div>'; };
  if(g && g.nVal){
    const d=r.d,dims=d.srcDims||(d._W0&&d._H0?[d._W0,d._H0]:null);
    /* A grade em memória pode ser a PRÉVIA reduzida que desenha o mapa. A
       resolução dela não é a do TIFF: o rótulo diz qual é qual, para ninguém
       tomar a célula da prévia pela resolução nativa do levantamento. */
    const semDimensoes=!dims&&typeof rasterPrecisaFonteTela==='function'&&rasterPrecisaFonteTela(d)&&!d._full,
      previa=dims?.length===2?(dims[0]!==g.nc||dims[1]!==g.nr):semDimensoes;
    if(dims?.length===2){li('Resolução nativa',fmtNum(g.nc*g.csx/dims[0],4)+' × '+fmtNum(g.nr*g.csy/dims[1],4)+' m');li('Fonte nativa',projectRasterReady(r)?'disponível':'localizar TIFF');}
    else if(semDimensoes){li('Resolução nativa','a do TIFF original');li('Fonte nativa','localizar TIFF');}
    li(previa?'Grade da prévia (mapa)':'Grade', g.nc+' × '+g.nr);
    li(previa?'Resolução da prévia (não nativa)':'Resolução', fmtNum(g.csx,3)+(Math.abs(g.csx-g.csy)>1e-6?' × '+fmtNum(g.csy,3):'')+' m');
    li('Células c/ dado', g.nVal.toLocaleString('pt-BR'));
    li('Área 2D', fmtNum(g.area2D,2)+' m²');
    li('Área 2D (ha)', fmtNum(g.area2D/1e4,4));
    if(g.area3D!=null){ li('Área 3D (superfície)', fmtNum(g.area3D,2)+' m²');
      li('Área 3D (ha)', fmtNum(g.area3D/1e4,4));
      li('Rugosidade (3D/2D)', fmtNum(g.area3D/g.area2D,4)); }
    li('Cota máx.', fmtNum(g.zmax,3)+' m');
    li('Cota mín.', fmtNum(g.zmin,3)+' m');
    li('Desnível', fmtNum(g.zmax-g.zmin,3)+' m');
    /* Quando a rampa é recortada no percentil, a legenda mostra outros números
       que estes. Sem dizer isso aqui, as duas telas parecem se contradizer. */
    try{
      const _st=r._st||(r._st=rasterStats(r.d));
      if(_st && _st.cauda)
        li('Faixa da legenda', fmtNum(_st.mn,2)+' – '+fmtNum(_st.mx,2)+' m <span style="opacity:.6">(percentil 2–98)</span>');
    }catch(e){}
  } else linhas='<div class="hint">Superfície sem células válidas.</div>';
  return '<label class="field">Propriedades — superfície (MDT)</label>'+
    '<div style="margin:2px 0 8px">'+(window.GeoMineRasterSourceUI?.nameHTML(r,'raster')||esc(r.name||'MDE'))+'</div>'+
    '<div style="border-top:1px dashed var(--line);padding-top:8px">'+
    '<label class="field">Geometria da superfície</label>'+
    '<div style="font-size:11.5px;line-height:1.5;margin-top:3px">'+linhas+'</div></div>';
}
/* FICHA DA ORTOFOTO NO PAINEL DE PROPRIEDADES — o mesmo cartão que o MDT tem.
   Clicar na ortofoto na árvore punha S.selRaster=S.img, mas propRefresh só
   reconhecia rasters de S.rasters: o painel caía em "Nenhuma camada ativa" e a
   ortofoto era a única camada sem ficha. Mesma estrutura, mesmos termos. */
function ppImageHTML(I){
  let linhas='';
  const li=(k,v)=>{ linhas+='<div style="display:flex;justify-content:space-between;gap:8px;padding:1px 0">'+
    '<span style="color:var(--ink-dim)">'+k+'</span><b style="font-family:var(--mono);font-size:11px">'+v+'</b></div>'; };
  const b=Array.isArray(I.b)?I.b.map(Number):null, temArq=!!(I._img0&&I._tiff);
  const W0=temArq?I._W0:(I._W0||null), H0=temArq?I._H0:(I._H0||null);
  const larg=b?(b[2]-b[0]):NaN, alt=b?(b[3]-b[1]):NaN;
  const cmpx=px=>(Number.isFinite(larg)&&px>0)?fmtNum(larg/px*100,1)+' cm/px':'—';
  const crs=(typeof orthoCRS==='function')?orthoCRS(I):S.workCRS;
  if(b && Number.isFinite(larg) && Number.isFinite(alt)){
    li('Prévia na tela', (I._w&&I._h)?I._w+' × '+I._h+' px':'—');
    li('Original', (W0&&H0)?W0+' × '+H0+' px'+(temArq?'':' <span style="opacity:.6">(não vinculado)</span>'):'<span style="opacity:.6">GeoTIFF não vinculado</span>');
    li('Resolução', (W0?cmpx(W0):cmpx(I._w||0))+((W0&&I._w&&I._w!==W0)?' <span style="opacity:.6">(prévia '+cmpx(I._w)+')</span>':''));
    li('Extensão X', fmtNum(b[0],2)+' – '+fmtNum(b[2],2));
    li('Extensão Y', fmtNum(b[1],2)+' – '+fmtNum(b[3],2));
    li('Tamanho', fmtNum(larg/1000,3)+' × '+fmtNum(alt/1000,3)+' km');
    li('Área', fmtNum(larg*alt/1e4,4)+' ha');
    li('CRS dos cantos', esc(CRS_LABELS[crs]||crs)+(I._crsFixo?' <span style="opacity:.6">(fixado)</span>':''));
    li('Sem-dado', (I._ndPct!=null&&isFinite(I._ndPct))?fmtNum(I._ndPct,1)+' % descartado':'—');
    li('Opacidade', fmtNum(((I.overlay&&I.overlay.options&&I.overlay.options.opacity!=null&&!(typeof _orthoGrid!=='undefined'&&_orthoGrid))?I.overlay.options.opacity:(typeof orthoOpacidade==='function'?orthoOpacidade():1))*100,0)+' %');
    const nativeError=typeof _orthoGrid!=='undefined'&&_orthoGrid?._nativeError;
    li('Tiles do original', !temArq?'localizar TIFF':nativeError?'prévia temporária · localizar original':S.orthoHD?'ativos'+(S.orthoDispFull?' · resolução original':''):'desligados (prévia)');
    li('Pirâmide (COG)', I._cog?(I._cog.nOv?I._cog.nOv+' nível(is)':'nenhuma'):'—');
    li('Arquivo', window.GeoMineRasterSourceUI?.nameHTML(I,'ortho',I.src?.file||I.name)||esc(I.src?.file||'—'));
    li('Pasta de trabalho', I.projectFile?esc(String(I.projectFile)):'<span style="opacity:.6">não gravada</span>');
  } else linhas='<div class="hint">Ortofoto sem extensão válida.</div>';
  return '<label class="field">Propriedades — ortofoto (imagem)</label>'+
    '<div style="margin:2px 0 8px">'+(window.GeoMineRasterSourceUI?.nameHTML(I,'ortho')||esc(I.name||'ortofoto'))+'</div>'+
    '<div style="border-top:1px dashed var(--line);padding-top:8px">'+
    '<label class="field">Geometria da imagem</label>'+
    '<div style="font-size:11.5px;line-height:1.5;margin-top:3px">'+linhas+'</div>'+
    '<div class="hint" style="margin-top:6px"><button type="button" class="gm-prop-info" data-prop-help="" aria-label="Ajuda: Opções da ortofoto" aria-expanded="false"><span aria-hidden="true">i</span><span hidden>Estilo, resolução, pasta de trabalho, exportação e CRS: ⚙ da ortofoto na árvore.</span></button></div></div>';
}
function propRefresh(){
  const d=document.getElementById('propDockContent')||document.getElementById('propDock');if(!d||!acadOn())return;
  if(S.selRaster&&(S.rasters||[]).includes(S.selRaster)&&!S.activeId){d.innerHTML=ppRasterHTML(S.selRaster);return;}
  if(S.selRaster&&S.img&&S.selRaster===S.img&&!S.activeId){d.innerHTML=ppImageHTML(S.img);return;}
  const L=(typeof activeLayer==='function')?activeLayer():null;
  if(!L){
    d.innerHTML='<label class="field">Propriedades</label><div class="hint">Nenhuma camada ativa. <button type="button" class="gm-prop-info" data-prop-help="" aria-label="Ajuda: Selecionar camada" aria-expanded="false"><span aria-hidden="true">i</span><span hidden>Toque numa camada ou superfície na lista para consultar suas propriedades.</span></button></div>';
    return;
  }
  const s=L.sym||{},q=L.attrFilter||{},temFlt=!!(q.enabled!==false&&q.field),nFlt=temFlt?attrFilterCount(L):L.features.length,
    c=labelCfg(L),expr=String(c.expr||'').trim(),rot=expr?'ƒx fórmula':(labelCampos(L).join(', ')||'desligado'),
    cls=s.mode==='grad'?'graduada por '+(s.field||'atributo'):s.mode==='cat'?'categorizada por '+(s.field||'atributo'):'símbolo único',
    vis=L.visible!==false?'visível':'oculta',fill=Math.round((L.fill||s.fill||0)*100),cor=L.color||s.color||'#000000';
  d.innerHTML=
    '<label class="field">'+(ppSelectedIndices(L).length?'Propriedades — seleção':'Propriedades — camada ativa')+'</label>'+
    '<div style="margin:3px 0 8px;font-size:14px"><b>'+esc(L.name)+'</b></div>'+
    '<div style="font-size:11.5px;line-height:1.5">'+
      ppMetricLine('Tipo',esc(L.gtype))+
      ppMetricLine('Feições da camada',temFlt?nFlt.toLocaleString('pt-BR')+' visíveis de '+L.features.length.toLocaleString('pt-BR'):L.features.length.toLocaleString('pt-BR'))+
      ppMetricLine('CRS da camada',esc(String(L.crs)))+
      ppMetricLine('Visibilidade',vis)+
      ppMetricLine('Bloqueio',L.locked?'bloqueada':'desbloqueada')+
      ppMetricLine('Classificação',esc(cls))+
      ppMetricLine('Cor principal','<span style="display:inline-block;width:10px;height:10px;border:1px solid #6f8190;background:'+esc(cor)+';vertical-align:-1px;margin-right:4px"></span>'+esc(cor))+
      ppMetricLine('Espessura',fmtNum(L.weight??s.weight??2,1)+' px')+
      (L.gtype==='polygon'?ppMetricLine('Preenchimento',fill+'%'):'')+
      ppMetricLine('Rótulo',esc(rot))+
      ppMetricLine('Filtro',temFlt?esc(q.field+' · '+nFlt+' de '+L.features.length):'sem filtro')+
    '</div>'+featureContinueHTML(L)+ppLayerGeomHTML(L)+ppAttrHTML(L);
  bindFeatureContinue(d,L);
}

/* O painel de propriedades ocupa uma coluna inteira no shell. Ele pode ser
   recolhido sem alterar a camada ativa ou perder os valores em edição. */
(function initPropDockToggle(){
  const b=document.getElementById('propDockToggle');if(!b)return;
  const KEY='ccmgisPropDockCollapsedV1';
  const aplica=(fechado,persistir=true)=>{
    fechado=!!fechado;document.body.classList.toggle('prop-dock-collapsed',fechado);
    b.textContent=fechado?'‹':'›';b.title=fechado?'Mostrar propriedades':'Recolher propriedades';
    b.setAttribute('aria-label',b.title);b.setAttribute('aria-expanded',String(!fechado));
    if(persistir)try{localStorage.setItem(KEY,fechado?'1':'0');}catch(e){}
  };
  let salvo=false;try{salvo=localStorage.getItem(KEY)==='1';}catch(e){}
  const estreita=window.matchMedia('(max-width:650px)');
  b.onclick=()=>{salvo=!document.body.classList.contains('prop-dock-collapsed');aplica(salvo);};
  /* Na tela de telefone o painel aberto ocupava quase todo o mapa e escondia
     as subabas. Recolher ao estreitar não altera a preferência de desktop. */
  const responsivo=()=>aplica(estreita.matches?true:salvo,false);
  window.GeoMinePropDock={restore(fechado){salvo=!!fechado;responsivo();}};
  if(estreita.addEventListener)estreita.addEventListener('change',responsivo);
  else estreita.addListener(responsivo);
  responsivo();
})();
(function(){
  // interface CCMGIS 3.0 sempre ativa; a ribbon usa a infraestrutura estável da 2.0
  document.body.classList.add('acad','alagis3');
  try{ localStorage.setItem(ACAD_KEY,'1'); }catch(e){}
  try{ if(typeof prefsApply==='function') prefsApply(); }catch(e){}
  { const x=document.getElementById('btnCloseRight'); if(x) x.style.display='none';
    const tb=document.getElementById('tabBar'); if(tb) tb.style.display='none'; }
  const b=document.getElementById('btnAcad');
  if(b){ b.onclick=()=>acadSet(!acadOn()); b.classList.toggle('on', acadOn()); }
  try{ ribbonBuild(); }catch(e){}
  try{ propRefresh(); }catch(e){}
})();

/* ---------- Limpeza: REMOVER SPIKES (pontas de ida-e-volta) ----------
   Spike = vértice em que a direção da linha reverte quase 180° (desvio
   ≥ ang) com pelo menos um dos lados curto (≤ lado). Remoção ITERATIVA
   até estabilizar; trata linhas abertas e anéis fechados (o vértice de
   fechamento é reavaliado). NUNCA mexe em vértice sem reversão — não é
   suavização: cantos legítimos ficam intactos.                        */
function limSpikeSeq(seq,zseq,ang,lado,fechada){
  const cosLim=Math.cos((180-ang)*Math.PI/180); /* desvio≥ang ⇔ cosθ ≤ −cos(180−ang) */
  let g=seq.map(p=>p.slice()),z=zseq?zseq.slice():null,rem=0,mexeu=true,guard=0;
  while(mexeu&&guard++<64){
    mexeu=false;
    const n=g.length;
    if(n<(fechada?4:3))break;
    for(let i=fechada?0:1;i<(fechada?n:n-1);i++){
      const ia=(i-1+n)%n,ic=(i+1)%n,
        a=g[ia],b=g[i],c=g[ic],
        v1x=b[0]-a[0],v1y=b[1]-a[1],v2x=c[0]-b[0],v2y=c[1]-b[1],
        l1=Math.hypot(v1x,v1y),l2=Math.hypot(v2x,v2y);
      if(l1<1e-9||l2<1e-9){g.splice(i,1);if(z)z.splice(i,1);rem++;mexeu=true;break;}
      const cos=(v1x*v2x+v1y*v2y)/(l1*l2);
      if(cos<=-cosLim&&Math.min(l1,l2)<=lado){
        g.splice(i,1);if(z)z.splice(i,1);rem++;mexeu=true;break;
      }
    }
  }
  return {g,z,rem};
}
function limRemoveSpikes(angId,ladoId,escId){
  const ang=parseFloat(String((document.getElementById(angId)||{}).value||'').replace(',','.')),
    lado=parseFloat(String((document.getElementById(ladoId)||{}).value||'').replace(',','.'));
  if(!isFinite(ang)||ang<90||ang>180){toast('Desvio mínimo entre 90° e 180°');return;}
  if(!isFinite(lado)||lado<=0){toast('Informe o lado máximo do spike em metros');return;}
  const esc2=(document.getElementById(escId)||{}).value||'todas',
    alvo=S.layers.filter(l=>l.gtype==='line'&&(esc2==='todas'||l.id===S.activeId));
  if(!alvo.length){toast(esc2==='ativa'?'A camada ativa não é de linhas':'Nenhuma camada de linhas no projeto');return;}
  let totV=0,totF=0;const det=[];
  for(const L of alvo){
    let vL=0;
    L.features.forEach(f=>{
      if(!f.geom||f.geom.length<3)return;
      const multi=!!(f.multi&&Array.isArray(f.geom[0]&&f.geom[0][0])),
        rs=multi?f.geom:[f.geom],
        zs=multi?(f.zg||rs.map(()=>null)):[f.zg||null];
      const novos=[],novosZ=[];let remF=0;
      rs.forEach((r,ri)=>{
        const fechada=r.length>3&&Math.hypot(r[0][0]-r[r.length-1][0],r[0][1]-r[r.length-1][1])<=0.02;
        let seq=r,zseq=zs[ri]||null,cauda=false;
        if(fechada){seq=r.slice(0,-1);zseq=zseq?zseq.slice(0,-1):null;cauda=true;}
        const res=limSpikeSeq(seq,zseq,ang,lado,fechada);
        remF+=res.rem;
        let gg=res.g,zz=res.z;
        if(cauda&&gg.length){gg=gg.concat([gg[0].slice()]);if(zz)zz=zz.concat([zz[0]]);}
        novos.push(gg);novosZ.push(zz);
      });
      if(remF>0){
        undoPush({t:'geom',L,f,geom:f.geom,multi:f.multi,zg:f.zg,msg:'spikes removidos'});
        f.geom=multi?novos:novos[0];
        if(f.zg!=null)f.zg=multi?novosZ:novosZ[0];
        vL+=remF;totF++;
      }
    });
    if(vL>0){det.push('• '+L.name+': '+vL+' vértice(s)');totV+=vL;drawLayer(L);}
  }
  refreshUI();
  if(typeof cmdLog==='function')cmdLog('limpeza: '+totV+' spike(s) removido(s) em '+totF+' feição(ões)','ok');
  toast(totV?('⚡ '+totV+' spike(s) removidos em '+totF+' feição(ões) — Ctrl+Z desfaz por feição\n'+det.join('\n')):
    'Nenhum spike encontrado no escopo (desvio ≥ '+ang+'°, lado ≤ '+lado+' m)');
}
function limLinhasCurtas(inpId, escId){
  const min=parseFloat(String((document.getElementById(inpId)||{}).value||'').replace(',','.'));
  if(!isFinite(min)||min<=0){ toast('Informe o comprimento mínimo em metros'); return; }
  const esc2=(document.getElementById(escId)||{}).value||'todas';
  const alvo=S.layers.filter(l=>l.gtype==='line' && (esc2==='todas' || l.id===S.activeId));
  if(!alvo.length){ toast(esc2==='ativa'? 'A camada ativa não é de linhas':'Nenhuma camada de linhas no projeto'); return; }
  const plano=[]; let tot=0;
  for(const L of alvo){
    const precisaReproj = String(L.crs||'')!==String(S.workCRS||'');
    const idxs=[];
    L.features.forEach((f,i)=>{
      if(!f.geom){ return; }
      const rs=(f.multi&&Array.isArray(f.geom[0][0]))?f.geom:[f.geom];
      let len=0;
      for(const r of rs){
        let prev=null;
        for(const p of r){
          const w=precisaReproj? reproj(L.crs,S.workCRS,p[0],p[1]) : p;
          if(prev) len+=Math.hypot(w[0]-prev[0], w[1]-prev[1]);
          prev=w;
          if(len>=min) break;                    // já passou do piso: não precisa somar o resto
        }
        if(len>=min) break;
      }
      if(len<min) idxs.push(i);
    });
    if(idxs.length){ plano.push({L, idxs}); tot+=idxs.length; }
  }
  if(!tot){ toast('Nenhuma linha com menos de '+min+' m no escopo'); return; }
  const det=plano.map(p=>'• '+p.L.name+': '+p.idxs.length).join('\n');
  if(!confirm('Descartar '+tot+' linha(s) com comprimento menor que '+min+' m?\n\n'+det+
    '\n\nCtrl+Z desfaz (uma camada por vez).')) return;
  for(const {L,idxs} of plano){
    idxs.sort((a,b)=>b-a);
    const rem=[];
    for(const i of idxs){ rem.push({idx:i, feat:L.features[i]}); L.features.splice(i,1); }
    undoPush({t:'mseldel', L, rem});             // mesmo desfazer da seleção múltipla
    drawLayer(L);
  }
  refreshUI();
  if(typeof cmdLog==='function') cmdLog('limpeza: '+tot+' linha(s) < '+min+' m descartada(s)','ok');
  toast(tot+' linha(s) curta(s) descartada(s) — Ctrl+Z desfaz');
}
function limRelatorio(){
  const a=limAnalisa();
  if(a.vazio){ toast('Nenhuma camada no escopo escolhido'); return; }
  const nada=!a.totF && !a.totV && !(a.camDup||[]).length && !(a.rasDup||[]).length;
  let html='';
  if(nada) html='<p style="margin:0;font-size:13px">Nada a limpar — nenhuma duplicata encontrada com tolerância de '+a.tol+' m.</p>';
  else{
    html='<div class="lp-info" style="margin-bottom:8px">Tolerância: <b>'+a.tol+' m</b></div>';
    if(a.porCamada.length){
      html+='<label class="field">Dentro das camadas</label><ul style="margin:0 0 8px;padding-left:18px;font-size:12px">';
      a.porCamada.forEach(({L,dup,vrem})=>{
        html+='<li><b>'+esc(L.name)+'</b>: '+(dup.length? dup.length+' feição(ões) idêntica(s)':'')+
          (dup.length&&vrem?' · ':'')+(vrem? vrem+' vértice(s) repetido(s)':'')+'</li>';
      });
      html+='</ul>';
    }
    if((a.camDup||[]).length){
      html+='<label class="field">Camadas duplicadas</label><ul style="margin:0 0 8px;padding-left:18px;font-size:12px">';
      a.camDup.forEach(g=>{ html+='<li>'+g.map(L=>esc(L.name)).join(' = ')+' → mantém a primeira</li>'; });
      html+='</ul>';
    }
    if((a.rasDup||[]).length){
      html+='<label class="field">Superfícies duplicadas</label><ul style="margin:0 0 8px;padding-left:18px;font-size:12px">';
      a.rasDup.forEach(g=>{ html+='<li>'+g.map(r=>esc(r.name)).join(' = ')+' → mantém a primeira</li>'; });
      html+='</ul>';
    }
  }
  const bg=document.createElement('div');
  bg.className='modal-bg on';
  bg.innerHTML='<div class="modal" style="width:min(560px,100%)">'+
    '<div class="modal-h"><b>Limpeza do projeto</b></div>'+
    '<div class="modal-b">'+html+
      '<div class="row2" style="margin-top:10px">'+
        (nada? '' : '<button class="tbtn" data-lm="ok" style="justify-content:center">🧹 Aplicar</button>')+
        '<button class="mini" data-lm="no" style="justify-content:center">Fechar</button>'+
      '</div>'+
      (nada? '' : '<div class="hint" style="margin-top:6px">Ctrl+Z desfaz feição a feição e camada a camada.</div>')+
    '</div></div>';
  document.body.appendChild(bg);
  const fim=()=>{ try{ bg.remove(); }catch(e){} };
  bg.querySelector('[data-lm="no"]').onclick=fim;
  bg.addEventListener('click',e=>{ if(e.target===bg) fim(); });
  const ok=bg.querySelector('[data-lm="ok"]');
  if(ok) ok.onclick=()=>{ limAplica(a); fim(); };
}

/* Larguras independentes de Camadas e Propriedades. As alças são irmãs dos
   painéis, por isso continuam acessíveis quando o conteúdo é rolado/recriado. */
(function(){
  function iniciarDivisorias(){
    const root=document.body,host=document.getElementById('body'),main=document.getElementById('main');
    if(!host||!main||host.dataset.gmPanelResize==='1')return;
    const specs=[
      {id:'right',gripId:'gmLayersResize',name:'Camadas',dir:1,min:200,initial:300,css:'--gm-layers-width',key:'geomine.panelWidth.layers.v1'},
      {id:'propDock',gripId:'gmPropertiesResize',name:'Propriedades',dir:-1,min:220,initial:270,css:'--gm-properties-width',key:'geomine.panelWidth.properties.v1'}
    ];
    const panels=specs.map(p=>({...p,el:document.getElementById(p.id)}));
    if(panels.some(p=>!p.el))return;
    host.dataset.gmPanelResize='1';
    const px=v=>parseFloat(v)||0,clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
    const collapsed=()=>root.classList.contains('prop-dock-collapsed');
    const shown=p=>root.classList.contains('alagis3')&&getComputedStyle(p.el).display!=='none'&&p.el.getClientRects().length>0;
    const usable=p=>shown(p)&&!(p.id==='propDock'&&collapsed());
    const floating=p=>['absolute','fixed'].includes(getComputedStyle(p.el).position);
    let frame=0,needsFit=false,drag=null,mapSize='',lastHostWidth=host.clientWidth,structure='';
    function apply(p,value){
      const width=Math.max(1,Math.round(value));
      if(p.width===width)return;
      p.width=width;root.style.setProperty(p.css,width+'px');
    }
    function remember(p,value){
      p.preferred=Math.round(value);
      try{localStorage.setItem(p.key,String(p.preferred));}catch(e){}
    }
    function metrics(){
      const s=getComputedStyle(host),width=Math.max(1,host.clientWidth-px(s.paddingLeft)-px(s.paddingRight));
      const flow=Array.from(host.children).filter(el=>{
        if(el===main||el.classList.contains('gm-panel-resizer'))return false;
        const c=getComputedStyle(el);
        return c.display!=='none'&&!['absolute','fixed'].includes(c.position)&&el.getBoundingClientRect().width>0;
      });
      const gap=px(s.columnGap),count=flow.length+(getComputedStyle(main).display!=='none'?1:0);
      return {width,flow,gap,spacing:Math.max(0,count-1)*gap,
        reserve:Math.min(320,Math.max(120,Math.round(width*.3)),width/2)};
    }
    function outerWidth(el){
      const s=getComputedStyle(el);
      return el.getBoundingClientRect().width+px(s.marginLeft)+px(s.marginRight);
    }
    function limits(p,m=metrics()){
      const available=floating(p)?m.width-Math.min(180,Math.max(64,m.width*.25)):
        m.width-m.spacing-m.reserve-m.flow.reduce((n,el)=>n+(el===p.el?0:outerWidth(el)),0);
      const max=Math.max(1,Math.floor(available));
      return {min:Math.min(p.min,max),max};
    }
    function fit(){
      if(host.clientWidth<100||!root.classList.contains('alagis3'))return;
      const m=metrics(),columns=panels.filter(p=>usable(p)&&m.flow.includes(p.el));
      const budget=Math.max(1,m.width-m.spacing-m.reserve-
        m.flow.reduce((n,el)=>n+(columns.some(p=>p.el===el)?0:outerWidth(el)),0));
      const minimum=columns.reduce((n,p)=>n+p.min,0),scale=Math.min(1,budget/(minimum||1));
      const bases=columns.map(p=>Math.floor(p.min*scale));
      const extra=columns.reduce((n,p,i)=>n+Math.max(0,p.preferred-bases[i]),0);
      const ratio=Math.min(1,Math.max(0,budget-bases.reduce((a,b)=>a+b,0))/(extra||1));
      columns.forEach((p,i)=>apply(p,Math.floor(bases[i]+Math.max(0,p.preferred-bases[i])*ratio)));
      for(const p of panels)if(usable(p)&&floating(p)){
        const b=limits(p,m);apply(p,clamp(p.preferred,b.min,b.max));
      }
    }
    function positionHandles(){
      const hr=host.getBoundingClientRect(),m=metrics(),readout=document.querySelector('.readout')?.getBoundingClientRect();
      const layers=panels[0],layerRect=layers.el.getBoundingClientRect();
      for(const p of panels){
        const g=p.grip,r=p.el.getBoundingClientRect(),x=p.dir===1?r.right+m.gap/2:r.left-m.gap/2;
        const top=Math.max(hr.top,r.top,0);
        let bottom=Math.min(hr.bottom,r.bottom,innerHeight);
        if(readout?.height&&readout.top>top)bottom=Math.min(bottom,readout.top-2);
        const covered=p.id==='propDock'&&usable(layers)&&floating(layers)&&x>=layerRect.left&&x<=layerRect.right;
        g.hidden=!usable(p)||r.width<1||bottom-top<24||covered;
        if(g.hidden)continue;
        g.style.left=clamp(x-hr.left-host.clientLeft+host.scrollLeft,6,host.clientWidth-6)+'px';
        g.style.top=(top-hr.top-host.clientTop+host.scrollTop)+'px';
        g.style.height=(bottom-top)+'px';
        const b=limits(p,m),width=Math.round(r.width);
        g.setAttribute('aria-valuemin',String(b.min));g.setAttribute('aria-valuemax',String(b.max));
        g.setAttribute('aria-valuenow',String(width));g.setAttribute('aria-valuetext',width+' pixels');
      }
    }
    function refreshMap(){
      const el=document.getElementById('map');if(!el||!el.clientWidth||!el.clientHeight)return;
      const size=el.clientWidth+'x'+el.clientHeight;if(size===mapSize)return;
      mapSize=size;
      try{if(typeof map!=='undefined'&&map?.invalidateSize)map.invalidateSize({pan:false});}catch(e){}
    }
    function flush(){
      frame=0;
      if(needsFit){needsFit=false;fit();}
      if(drag&&drag.pending!=null){
        const b=limits(drag.panel);apply(drag.panel,clamp(drag.pending,b.min,b.max));drag.pending=null;
      }
      positionHandles();refreshMap();
    }
    function schedule(refit=false){
      if(refit)needsFit=true;
      if(!frame)frame=requestAnimationFrame(flush);
    }
    function move(e){
      if(!drag||e.pointerId!==drag.pointerId)return;
      drag.pending=drag.startWidth+(e.clientX-drag.startX)*drag.panel.dir;
      e.preventDefault();e.stopPropagation();schedule();
    }
    function finish(commit){
      if(!drag)return;
      const d=drag;drag=null;
      document.removeEventListener('pointermove',move,true);
      document.removeEventListener('pointerup',up,true);
      document.removeEventListener('pointercancel',cancel,true);
      document.removeEventListener('keydown',cancelKey,true);
      const b=limits(d.panel),width=commit?(d.pending??d.panel.width):d.startWidth;
      apply(d.panel,clamp(width,b.min,b.max));
      if(commit)remember(d.panel,d.panel.width);
      d.panel.grip.classList.remove('dragging');root.classList.remove('gm-panel-resizing');
      try{if(d.panel.grip.hasPointerCapture(d.pointerId))d.panel.grip.releasePointerCapture(d.pointerId);}catch(e){}
      schedule();
    }
    function up(e){if(drag&&e.pointerId===drag.pointerId){e.preventDefault();e.stopPropagation();finish(true);}}
    function cancel(e){if(drag&&e.pointerId===drag.pointerId)finish(false);}
    function cancelKey(e){if(drag&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();finish(false);}}
    for(const p of panels){
      let saved=NaN;try{saved=Number(localStorage.getItem(p.key));}catch(e){}
      p.preferred=Number.isFinite(saved)&&saved>=80&&saved<=10000?Math.round(saved):p.initial;
      apply(p,p.preferred);
      const g=document.createElement('div');p.grip=g;g.id=p.gripId;g.className='gm-panel-resizer';g.hidden=true;g.tabIndex=0;
      g.dataset.panel=p.id;g.setAttribute('role','separator');g.setAttribute('aria-orientation','vertical');
      g.setAttribute('aria-controls',p.id);g.setAttribute('aria-label','Largura do painel '+p.name);
      g.title=p.name+': arraste para ajustar a largura. Setas ajustam; duplo clique restaura o padrão.';
      g.addEventListener('pointerdown',e=>{
        if(drag||!usable(p)||e.isPrimary===false||(e.pointerType==='mouse'&&e.button!==0))return;
        e.preventDefault();e.stopPropagation();g.focus({preventScroll:true});
        // Conclui a transição do dock antes de medir a origem do arrasto.
        root.classList.add('gm-panel-resizing');g.classList.add('dragging');
        drag={panel:p,pointerId:e.pointerId,startX:e.clientX,startWidth:p.el.getBoundingClientRect().width,pending:null};
        document.addEventListener('pointermove',move,{capture:true,passive:false});
        document.addEventListener('pointerup',up,true);document.addEventListener('pointercancel',cancel,true);
        document.addEventListener('keydown',cancelKey,true);
        try{g.setPointerCapture(e.pointerId);}catch(err){}
      });
      g.addEventListener('lostpointercapture',e=>{if(drag&&e.pointerId===drag.pointerId)finish(false);});
      g.addEventListener('keydown',e=>{
        if(drag||e.altKey||e.ctrlKey||e.metaKey||!usable(p))return;
        const b=limits(p),current=p.el.getBoundingClientRect().width,step=e.shiftKey?40:10;
        let value;
        if(e.key==='ArrowLeft')value=current-step*p.dir;
        else if(e.key==='ArrowRight')value=current+step*p.dir;
        else if(e.key==='Home')value=b.min;
        else if(e.key==='End')value=b.max;
        else return;
        e.preventDefault();e.stopPropagation();apply(p,clamp(value,b.min,b.max));remember(p,p.width);schedule();
      });
      g.addEventListener('dblclick',e=>{
        e.preventDefault();e.stopPropagation();if(drag)finish(false);
        const b=limits(p);apply(p,clamp(p.initial,b.min,b.max));remember(p,p.initial);schedule();
      });
      host.appendChild(g);
    }
    const structuralState=()=>[root.classList.contains('alagis3'),collapsed(),
      ...panels.flatMap(p=>[shown(p),floating(p)])].join('|');
    structure=structuralState();
    const mutation=new MutationObserver(()=>{
      const next=structuralState(),changed=next!==structure;structure=next;
      if(changed&&drag)finish(false);schedule(changed);
    });
    mutation.observe(root,{attributes:true,attributeFilter:['class']});
    panels.forEach(p=>mutation.observe(p.el,{attributes:true,attributeFilter:['class','style','hidden']}));
    // O orçamento inicial pode ser medido no meio da animação de recolher.
    panels[1].el.addEventListener('transitionend',e=>{
      if(e.target===panels[1].el&&!drag)schedule(true);
    });
    if(window.ResizeObserver){
      const observer=new ResizeObserver(()=>{
        const width=host.clientWidth,changed=width!==lastHostWidth;lastHostWidth=width;
        if(changed&&drag)finish(false);schedule(changed);
      });
      [host,main,...panels.map(p=>p.el)].forEach(el=>observer.observe(el));
      const el=document.getElementById('map');if(el)observer.observe(el);
    }
    window.addEventListener('resize',()=>{if(drag)finish(false);schedule(true);},{passive:true});
    window.addEventListener('blur',()=>finish(false));
    window.addEventListener('pageshow',()=>schedule(true));
    document.addEventListener('visibilitychange',()=>{if(document.hidden)finish(false);});
    if(window.visualViewport){
      window.visualViewport.addEventListener('resize',()=>schedule(),{passive:true});
      window.visualViewport.addEventListener('scroll',()=>schedule(),{passive:true});
    }
    schedule(true);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',iniciarDivisorias,{once:true});
  else iniciarDivisorias();
})();
